const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').split(/\s+/).filter(Boolean);

const n = +input[0];
const s = +input[1];

// Soma total máxima: 100000 * 10 = 1.000.000, então prefixos cabem no array
const freq = new Uint32Array(1000002);
freq[0] = 1; // prefixo vazio (soma 0)

